import re
from datetime import timezone

from pydantic import BaseModel, ConfigDict

from mirage.backends.base import BaseBackend
from mirage.backends.filetype import guess_type
from mirage.types import FileStat, FileType


class S3Config(BaseModel):
    model_config = ConfigDict(frozen=True)

    bucket: str
    region: str | None = None
    endpoint_url: str | None = None
    aws_access_key_id: str | None = None
    aws_secret_access_key: str | None = None
    aws_profile: str | None = None
    timeout: int = 30
    proxy: str | None = None
    select_threshold_bytes: int | None = 1 * 1024 * 1024  # 1 MB


class S3Backend(BaseBackend):
    """
    S3-compatible backend using boto3.

    Requires: pip install mirage[s3]

    Key design decisions:
    - read()  → GetObject with Range header (partial reads)
    - readdir() → list_objects_v2 with paginator (handles >1000 keys)
    - write()  → full PutObject (S3 has no partial write)
    - grep()   → S3 Select for large files, full fetch for small files
    - ls_l()   → list_objects_v2 already returns size+mtime, skip per-file stat
    """

    def __init__(self, config: S3Config) -> None:
        self.config = config
        self._client = self._make_client()

    def _make_client(self):
        try:
            import boto3
            from botocore.config import Config
        except ImportError:
            raise ImportError(
                "boto3 is required for S3Backend: pip install 'mirage[s3]'")

        kwargs: dict = {"service_name": "s3"}
        c = self.config
        if c.region:
            kwargs["region_name"] = c.region
        if c.endpoint_url:
            kwargs["endpoint_url"] = c.endpoint_url
        if c.aws_access_key_id and c.aws_secret_access_key:
            kwargs["aws_access_key_id"] = c.aws_access_key_id
            kwargs["aws_secret_access_key"] = c.aws_secret_access_key

        cfg_kwargs: dict = {
            "connect_timeout": c.timeout,
            "read_timeout": c.timeout
        }
        if c.proxy:
            cfg_kwargs["proxies"] = {"https": c.proxy, "http": c.proxy}

        kwargs["config"] = Config(**cfg_kwargs)

        if c.aws_profile:
            session = boto3.Session(profile_name=c.aws_profile)
            return session.client(**kwargs)
        return boto3.client(**kwargs)

    # ── key helpers ─────────────────────────────────────────────────────────

    def _key(self, path: str) -> str:
        """Convert virtual path to S3 key (strip leading slash)."""
        return path.lstrip("/")

    def _prefix(self, path: str) -> str:
        """Directory prefix — always ends with '/' unless root."""
        key = self._key(path)
        if key and not key.endswith("/"):
            key += "/"
        return key

    # ── ops ─────────────────────────────────────────────────────────────────

    def read(self, path: str, offset: int, size: int) -> bytes:
        end = offset + size - 1
        resp = self._client.get_object(
            Bucket=self.config.bucket,
            Key=self._key(path),
            Range=f"bytes={offset}-{end}",
        )
        return resp["Body"].read()

    def readdir(self,
                path: str,
                cursor: str | None = None) -> tuple[list[str], str | None]:
        prefix = self._prefix(path)
        kwargs: dict = {
            "Bucket": self.config.bucket,
            "Prefix": prefix,
            "Delimiter": "/",
        }
        if cursor:
            kwargs["ContinuationToken"] = cursor

        resp = self._client.list_objects_v2(**kwargs)

        names: list[str] = []
        # common prefixes = subdirectories
        for cp in resp.get("CommonPrefixes") or []:
            p = cp["Prefix"]
            child = p.rstrip("/")
            if child:
                names.append(child)
        # object keys = files
        for obj in resp.get("Contents") or []:
            key = obj["Key"]
            relative = key[len(prefix):]
            if relative and "/" not in relative:  # direct children only
                names.append(key)

        next_cursor = resp.get("NextContinuationToken")
        return sorted(names), next_cursor

    def stat(self, path: str) -> FileStat:
        try:
            resp = self._client.head_object(Bucket=self.config.bucket,
                                            Key=self._key(path))
            modified = resp["LastModified"].astimezone(
                timezone.utc).isoformat()
            return FileStat(
                name=path.rstrip("/").rsplit("/", 1)[-1],
                size=resp["ContentLength"],
                modified=modified,
                type=_guess_type(path),
                extra={"etag": resp.get("ETag", "").strip('"')},
            )
        except self._client.exceptions.NoSuchKey:
            pass
        except Exception as exc:
            if not (hasattr(exc, "response")
                    and exc.response.get("Error", {}).get("Code") == "404"):
                raise
        # key not found — check if it's a directory prefix
        prefix = self._prefix(path)
        resp = self._client.list_objects_v2(Bucket=self.config.bucket,
                                            Prefix=prefix,
                                            MaxKeys=1)
        if resp.get("Contents") or resp.get("CommonPrefixes"):
            return FileStat(
                name=path.rstrip("/").rsplit("/", 1)[-1] or "/",
                size=None,
                type=FileType.DIRECTORY,
            )
        raise FileNotFoundError(path)

    def open(self, path: str, flags: int) -> int:
        raise NotImplementedError("open/release are FUSE-only")

    def release(self, fh: int) -> None:
        raise NotImplementedError("open/release are FUSE-only")

    def write(self, path: str, offset: int, data: bytes) -> int:
        # S3 has no partial write — we must do full replace
        if offset != 0:
            # fetch existing, splice, re-upload
            existing = self.cat(path)
            data = existing[:offset] + data + existing[offset + len(data):]
        self._client.put_object(Bucket=self.config.bucket,
                                Key=self._key(path),
                                Body=data)
        return len(data)

    def create(self, path: str) -> None:
        self._client.put_object(Bucket=self.config.bucket,
                                Key=self._key(path),
                                Body=b"")

    def unlink(self, path: str) -> None:
        self._client.delete_object(Bucket=self.config.bucket,
                                   Key=self._key(path))

    def rmdir(self, path: str) -> None:
        prefix = self._prefix(path)
        paginator = self._client.get_paginator("list_objects_v2")
        for page in paginator.paginate(Bucket=self.config.bucket,
                                       Prefix=prefix):
            keys = [{"Key": obj["Key"]} for obj in page.get("Contents") or []]
            if keys:
                self._client.delete_objects(Bucket=self.config.bucket,
                                            Delete={"Objects": keys})

    def mkdir(self, path: str) -> None:
        # S3 has no real directories — key prefix convention
        prefix = self._prefix(path)
        if prefix:
            self._client.put_object(Bucket=self.config.bucket,
                                    Key=prefix,
                                    Body=b"")

    def rename(self, src: str, dst: str) -> None:
        self._client.copy_object(
            Bucket=self.config.bucket,
            CopySource={
                "Bucket": self.config.bucket,
                "Key": self._key(src)
            },
            Key=self._key(dst),
        )
        self._client.delete_object(Bucket=self.config.bucket,
                                   Key=self._key(src))

    def truncate(self, path: str, size: int) -> None:
        data = self.cat(path)
        if size < len(data):
            data = data[:size]
        else:
            data = data + b"\x00" * (size - len(data))
        self._client.put_object(Bucket=self.config.bucket,
                                Key=self._key(path),
                                Body=data)

    # ── native overrides ────────────────────────────────────────────────────

    def ls_l(self, path: str) -> list[FileStat]:
        """list_objects_v2 returns size+mtime — skip per-file stat."""
        prefix = self._prefix(path)
        stats: list[FileStat] = []
        paginator = self._client.get_paginator("list_objects_v2")
        for page in paginator.paginate(Bucket=self.config.bucket,
                                       Prefix=prefix,
                                       Delimiter="/"):
            for cp in page.get("CommonPrefixes") or []:
                name = cp["Prefix"][len(prefix):].rstrip("/")
                stats.append(
                    FileStat(name=name, size=None, type=FileType.DIRECTORY))
            for obj in page.get("Contents") or []:
                key = obj["Key"]
                name = key[len(prefix):]
                if name and "/" not in name:
                    modified = obj["LastModified"].astimezone(
                        timezone.utc).isoformat()
                    stats.append(
                        FileStat(name=name,
                                 size=obj["Size"],
                                 modified=modified,
                                 type=_guess_type(name)))
        return stats

    def head(self, path: str, lines: int = 10) -> bytes:
        threshold = self.config.select_threshold_bytes
        if threshold is not None:
            try:
                s = self.stat(path)
                if s.size and s.size > threshold:
                    return self._head_select(path, lines)
            except FileNotFoundError:
                pass
        return super().head(path, lines)

    def _head_select(self, path: str, lines: int) -> bytes:
        sql = f"SELECT * FROM S3Object LIMIT {int(lines)}"
        try:
            resp = self._client.select_object_content(
                Bucket=self.config.bucket,
                Key=self._key(path),
                ExpressionType="SQL",
                Expression=sql,
                InputSerialization={
                    "CSV": {
                        "FileHeaderInfo": "NONE"
                    },
                    "CompressionType": "NONE"
                },
                OutputSerialization={"CSV": {}},
            )
            parts: list[str] = []
            for event in resp["Payload"]:
                if "Records" in event:
                    parts.extend(
                        event["Records"]["Payload"].decode().splitlines())
            return "\n".join(parts[:lines]).encode()
        except Exception:
            return super().head(path, lines)

    def presign(self, path: str, expires: int = 3600) -> str:
        return self._client.generate_presigned_url(
            "get_object",
            Params={
                "Bucket": self.config.bucket,
                "Key": self._key(path)
            },
            ExpiresIn=expires,
        )

    def grep(self, pattern: str, path: str, flags: int = 0) -> list[str]:
        """S3 Select for large files; full fetch for small files."""
        threshold = self.config.select_threshold_bytes
        if threshold is not None:
            try:
                s = self.stat(path)
                if s.size and s.size > threshold:
                    return self._grep_select(pattern, path)
            except FileNotFoundError:
                pass
        return super().grep(pattern, path, flags)

    def _grep_select(self, pattern: str, path: str) -> list[str]:
        """S3 Select LIKE filter — regex unsupported, re-filtered in Python."""
        escaped = (pattern.replace("'",
                                   "''").replace("%",
                                                 "\\%").replace("_", "\\_"))
        sql = f"SELECT * FROM S3Object WHERE _1 LIKE '%{escaped}%'"
        try:
            resp = self._client.select_object_content(
                Bucket=self.config.bucket,
                Key=self._key(path),
                ExpressionType="SQL",
                Expression=sql,
                InputSerialization={
                    "CSV": {
                        "FileHeaderInfo": "NONE"
                    },
                    "CompressionType": "NONE"
                },
                OutputSerialization={"CSV": {}},
            )
            lines: list[str] = []
            for event in resp["Payload"]:
                if "Records" in event:
                    lines.extend(
                        event["Records"]["Payload"].decode().splitlines())
            compiled = re.compile(pattern)
            return [line for line in lines if compiled.search(line)]
        except Exception:
            return super().grep(pattern, path)

from pydantic import BaseModel, ConfigDict, Field

from mirage.backends.base import BaseBackend
from mirage.backends.filetype import guess_type
from mirage.types import FileStat


class HTTPConfig(BaseModel):
    model_config = ConfigDict(frozen=True, arbitrary_types_allowed=True)

    base_url: str
    headers: dict[str, str] = Field(default_factory=dict)
    timeout: int = 30
    readdir_fn: object = None


class HTTPBackend(BaseBackend):
    """
    Read-only HTTP backend using httpx.

    Maps virtual paths to URLs: base_url + path
    e.g. base_url="https://data.example.com", path="/q1.json"
         → GET https://data.example.com/q1.json

    Requires: pip install mirage[http]

    Write ops (write, create, unlink, etc.) raise NotImplementedError —
    HTTP is read-only by design. Override to support writable HTTP APIs.

    readdir() requires a user-supplied `readdir_fn` since HTTP has no
    standard directory listing protocol.
    """

    def __init__(self, config: HTTPConfig) -> None:
        self.config = config
        self._client = self._make_client()

    def _make_client(self):
        try:
            import httpx
        except ImportError:
            raise ImportError(
                "httpx is required for HTTPBackend: pip install 'mirage[http]'"
            )
        return httpx.Client(
            base_url=self.config.base_url,
            headers=self.config.headers,
            timeout=self.config.timeout,
            follow_redirects=True,
        )

    def _url(self, path: str) -> str:
        return self.config.base_url.rstrip("/") + "/" + path.lstrip("/")

    # ── ops ─────────────────────────────────────────────────────────────────

    def read(self, path: str, offset: int, size: int) -> bytes:
        headers = {"Range": f"bytes={offset}-{offset + size - 1}"}
        resp = self._client.get(self._url(path), headers=headers)
        if resp.status_code == 416:
            return b""
        resp.raise_for_status()
        return resp.content

    def readdir(self,
                path: str,
                cursor: str | None = None) -> tuple[list[str], str | None]:
        if self.config.readdir_fn is None:
            raise NotImplementedError(
                "HTTPBackend.readdir() requires a readdir_fn in HTTPConfig. "
                "Provide a callable(path) -> list[str] for your API.")
        names = self.config.readdir_fn(path)
        return names, None

    def stat(self, path: str) -> FileStat:
        resp = self._client.head(self._url(path))
        if resp.status_code == 404:
            raise FileNotFoundError(path)
        resp.raise_for_status()
        size = int(resp.headers.get("content-length", 0)) or None
        modified = resp.headers.get("last-modified")
        etag = resp.headers.get("etag", "").strip('"') or None
        extra = {"etag": etag} if etag else {}
        return FileStat(
            name=path.rstrip("/").rsplit("/", 1)[-1],
            size=size,
            modified=modified,
            type=_guess_type(path),
            extra=extra,
        )

    def open(self, path: str, flags: int) -> int:
        raise NotImplementedError("open/release are FUSE-only")

    def release(self, fh: int) -> None:
        raise NotImplementedError("open/release are FUSE-only")

    # ── write ops — not supported ────────────────────────────────────────────

    def write(self, path: str, offset: int, data: bytes) -> int:
        raise NotImplementedError("HTTPBackend is read-only")

    def create(self, path: str) -> None:
        raise NotImplementedError("HTTPBackend is read-only")

    def unlink(self, path: str) -> None:
        raise NotImplementedError("HTTPBackend is read-only")

    def rmdir(self, path: str) -> None:
        raise NotImplementedError("HTTPBackend is read-only")

    def mkdir(self, path: str) -> None:
        raise NotImplementedError("HTTPBackend is read-only")

    def rename(self, src: str, dst: str) -> None:
        raise NotImplementedError("HTTPBackend is read-only")

    def truncate(self, path: str, size: int) -> None:
        raise NotImplementedError("HTTPBackend is read-only")

import hashlib
from datetime import datetime, timezone

from mirage.backends.base import BaseBackend
from mirage.backends.filetype import guess_type
from mirage.types import FileStat, FileType


class MemoryBackend(BaseBackend):
    """
    In-memory backend backed by a plain dict. No external dependencies.
    Useful for tests, ephemeral scratch space, and as a cache target.

    Internal layout:
        _files: dict[str, bytes]  — path → content
        _dirs:  set[str]          — explicit directory paths
    """

    def __init__(self) -> None:
        self._files: dict[str, bytes] = {}
        self._dirs: set[str] = {"/"}
        self._modified: dict[str, str] = {}  # path → ISO timestamp

    # ── helpers ─────────────────────────────────────────────────────────────

    def _norm(self, path: str) -> str:
        """Normalise to absolute path without trailing slash."""
        p = "/" + path.strip("/")
        return p

    def _now(self) -> str:
        return datetime.now(timezone.utc).isoformat()

    def _parent(self, path: str) -> str:
        parts = path.rsplit("/", 1)
        return parts[0] or "/"

    # ── ops ─────────────────────────────────────────────────────────────────

    def read(self, path: str, offset: int, size: int) -> bytes:
        p = self._norm(path)
        if p not in self._files:
            raise FileNotFoundError(p)
        return self._files[p][offset:offset + size]

    def readdir(self,
                path: str,
                cursor: str | None = None) -> tuple[list[str], str | None]:
        p = self._norm(path)
        if p not in self._dirs:
            raise FileNotFoundError(p)
        prefix = p.rstrip("/") + "/"
        # direct children only
        seen: set[str] = set()
        for key in list(self._files) + list(self._dirs):
            if key == p:
                continue
            if key.startswith(prefix):
                remainder = key[len(prefix):]
                child = remainder.split("/")[0]
                if child:
                    seen.add(prefix + child)
        names = sorted(seen)
        # simple offset-based pagination via cursor
        start = int(cursor) if cursor else 0
        page = names[start:]
        return page, None  # no pagination needed for in-memory

    def stat(self, path: str) -> FileStat:
        p = self._norm(path)
        if p in self._dirs:
            return FileStat(name=p.rsplit("/", 1)[-1] or "/",
                            size=None,
                            modified=self._modified.get(p),
                            type=FileType.DIRECTORY)
        if p in self._files:
            data = self._files[p]
            return FileStat(
                name=p.rsplit("/", 1)[-1],
                size=len(data),
                modified=self._modified.get(p),
                type=guess_type(p),
            )
        raise FileNotFoundError(p)

    def open(self, path: str, flags: int) -> int:
        raise NotImplementedError("open/release are FUSE-only")

    def release(self, fh: int) -> None:
        raise NotImplementedError("open/release are FUSE-only")

    def write(self, path: str, offset: int, data: bytes) -> int:
        p = self._norm(path)
        if p not in self._files:
            raise FileNotFoundError(p)
        existing = self._files[p]
        # pad if offset beyond current size
        if offset > len(existing):
            existing = existing + b"\x00" * (offset - len(existing))
        self._files[p] = existing[:offset] + data + existing[offset +
                                                             len(data):]
        self._modified[p] = self._now()
        return len(data)

    def create(self, path: str) -> None:
        p = self._norm(path)
        parent = self._parent(p)
        if parent != "/" and parent not in self._dirs:
            raise FileNotFoundError(
                f"parent directory does not exist: {parent}")
        self._files[p] = b""
        self._modified[p] = self._now()

    def unlink(self, path: str) -> None:
        p = self._norm(path)
        if p not in self._files:
            raise FileNotFoundError(p)
        del self._files[p]
        self._modified.pop(p, None)

    def rmdir(self, path: str) -> None:
        p = self._norm(path)
        if p not in self._dirs:
            raise FileNotFoundError(p)
        prefix = p.rstrip("/") + "/"
        children = [
            k for k in list(self._files) + list(self._dirs)
            if k.startswith(prefix) and k != p
        ]
        if children:
            raise OSError(f"directory not empty: {p}")
        self._dirs.discard(p)

    def mkdir(self, path: str) -> None:
        p = self._norm(path)
        parent = self._parent(p)
        if parent != "/" and parent not in self._dirs:
            raise FileNotFoundError(
                f"parent directory does not exist: {parent}")
        self._dirs.add(p)
        self._modified[p] = self._now()

    def rename(self, src: str, dst: str) -> None:
        s, d = self._norm(src), self._norm(dst)
        if s in self._files:
            self._files[d] = self._files.pop(s)
            self._modified[d] = self._modified.pop(s, self._now())
        elif s in self._dirs:
            self._dirs.discard(s)
            self._dirs.add(d)
            self._modified[d] = self._modified.pop(s, self._now())
            # move all children
            prefix = s.rstrip("/") + "/"
            for key in list(self._files):
                if key.startswith(prefix):
                    new_key = d.rstrip("/") + "/" + key[len(prefix):]
                    self._files[new_key] = self._files.pop(key)
        else:
            raise FileNotFoundError(s)

    def truncate(self, path: str, size: int) -> None:
        p = self._norm(path)
        if p not in self._files:
            raise FileNotFoundError(p)
        data = self._files[p]
        if size < len(data):
            self._files[p] = data[:size]
        else:
            self._files[p] = data + b"\x00" * (size - len(data))
        self._modified[p] = self._now()

    # ── convenience ─────────────────────────────────────────────────────────

    def checksum(self, path: str) -> str:
        p = self._norm(path)
        return hashlib.md5(self._files[p]).hexdigest()


def _guess_type(path: str) -> str | None:
    ext = path.rsplit(".", 1)[-1].lower() if "." in path else ""
    return {
        "json": "json",
        "jsonl": "json",
        "csv": "csv",
        "tsv": "csv",
        "txt": "text",
        "md": "text",
        "py": "text",
        "js": "text",
        "ts": "text",
        "yaml": "text",
        "yml": "text",
        "toml": "text",
    }.get(ext)

