_MAX_PREVIEW_ROWS = 20


class ParquetFuseOp(FuseOp):

    name = "parquet"

    def on_open(self, ws: Workspace, path: str, size: int) -> dict:
        return {"eager": True, "virtual": True}

    def read(self, ws: Workspace, path: str, offset: int, size: int,
             ctx: dict) -> bytes:
        if "data" not in ctx:
            ctx["data"] = self._render(ws, path)
        return ctx["data"][offset:offset + size]

    def _render(self, ws: Workspace, path: str) -> bytes:
        try:
            import pyarrow.parquet as pq

            raw = ws.cat(path)
            pf = pq.ParquetFile(io.BytesIO(raw))
            schema = pf.schema_arrow
            num_rows = pf.metadata.num_rows
            table = pf.read_row_groups([0]).slice(0, _MAX_PREVIEW_ROWS)
            preview_rows = min(num_rows, _MAX_PREVIEW_ROWS)
            lines = [
                f"# Parquet: {path}",
                f"# Rows: {num_rows}, Columns: {len(schema)}",
                "",
                "## Schema",
            ]
            for field in schema:
                lines.append(f"  {field.name}: {field.type}")
            lines.append("")
            lines.append(f"## Preview (first {preview_rows} rows)")
            lines.append("")
            lines.append(table.to_pandas().to_string(index=False))
            lines.append("")
            return "\n".join(lines).encode()
        except Exception as e:
            return f"# Error reading parquet: {e}\n".encode()

