class FuseOpRegistry:

    def __init__(self) -> None:
        self._ops: list[tuple[str, FuseOp]] = []
        self._default: FuseOp = FUSE_OPS["default"]

    def register(self, pattern: str, op: FuseOp) -> None:
        self._ops.append((pattern, op))

    def set_default(self, op: FuseOp) -> None:
        self._default = op

    def resolve(self,
                path: str,
                size: int,
                ws: Workspace | None = None) -> FuseOp:
        basename = path.rsplit("/", 1)[-1] if "/" in path else path
        for pattern, op in self._ops:
            if fnmatch.fnmatch(basename, pattern):
                return op
        if ws is not None:
            try:
                backend, _, _ = ws._registry.resolve(path)
                backend_name = type(backend).__name__
                op_key = _BACKEND_OP_MAP.get(backend_name)
                if op_key and op_key in FUSE_OPS:
                    return FUSE_OPS[op_key]
            except (ValueError, FileNotFoundError):
                pass
        return self._default

    def list_ops(self) -> list[dict]:
        ops = [{"pattern": p, "name": o.name} for p, o in self._ops]
