        ops = [{"pattern": p, "name": o.name} for p, o in self._ops]
        ops.append({"pattern": "*", "name": self._default.name})
        return ops

import importlib
import importlib.util
from typing import Any

from mirage.fuse_ops import FUSE_OPS
from mirage.fuse_ops.registry import FuseOpRegistry


def load_fuse_op_class(spec: str) -> type[Any]:
    if ":" not in spec:
        raise ValueError(
            f"invalid fuse op spec {spec!r}, expected 'source:ClassName'")

    source, class_name = spec.rsplit(":", 1)

    if "/" in source or source.endswith(".py"):
        module_spec = importlib.util.spec_from_file_location(
            "_mirage_user_fuse_op", source)
        if module_spec is None or module_spec.loader is None:
            raise ValueError(f"cannot load script {source!r}")
        module = importlib.util.module_from_spec(module_spec)
        try:
            module_spec.loader.exec_module(module)
        except FileNotFoundError:
            raise ValueError(f"cannot load script {source!r}")
    else:
        module = importlib.import_module(source)

    if not hasattr(module, class_name):
        raise ValueError(f"{class_name!r} not found in {source!r}")

    return getattr(module, class_name)


def build_registry_from_config(fuse_ops: dict) -> FuseOpRegistry:
    registry = FuseOpRegistry()
    for pattern, value in fuse_ops.items():
        if isinstance(value, str):
            if value in FUSE_OPS:
                registry.register(pattern, FUSE_OPS[value])
            else:
                cls = load_fuse_op_class(value)
                registry.register(pattern, cls())
        elif isinstance(value, dict):
            handler = value.get("handler", "")
            if handler in FUSE_OPS:
                registry.register(pattern, FUSE_OPS[handler])
            else:
                cls = load_fuse_op_class(handler)
                args = value.get("args", {})
                registry.register(pattern, cls(**args))
    return registry

import errno
import os
import stat
import subprocess
import sys
import threading
import time
import uuid
from collections import deque
from datetime import datetime, timezone

import fuse
from mirage.fuse_ops.base import FuseOp
from mirage.fuse_ops.registry import FuseOpRegistry
from mirage.workspace import Workspace

_ENV_AGENT_ID = "MIRAGE_AGENT_ID"
_MIRAGE_DIR = "/.mirage"
_MIRAGE_WHOAMI = "/.mirage/whoami"

_MAX_OPS = 200


class MirageFS(fuse.Operations):

    def __init__(self,
                 ws: Workspace,
                 agent_id: str | None = None,
                 fuse_registry: FuseOpRegistry | None = None) -> None:
        self.ws = ws
        self.agent_id = (agent_id or os.environ.get(_ENV_AGENT_ID)
                         or f"agent-{uuid.uuid4().hex[:8]}")
        self._now = time.time()
        self._prefixes = [m.prefix for m in ws._registry._mounts]
        self._ops: deque[dict] = deque(maxlen=_MAX_OPS)
        self._ops_lock = threading.Lock()
        self._read_seen: set[str] = set()
        self._fuse_registry = fuse_registry or FuseOpRegistry()
        self._handles: dict[int, dict] = {}
        self._handle_ops: dict[int, FuseOp] = {}
        self._next_fh = 1

    def _whoami_content(self) -> bytes:
        mounts = [m.prefix for m in self.ws._registry._mounts]
        lines = [
            f"agent: {self.agent_id}",
            "cwd: /",
            f"mounts: {', '.join(mounts)}",
        ]
        return ("\n".join(lines) + "\n").encode()

    def _dir_stat(self) -> dict:
        return {
            "st_mode": stat.S_IFDIR | 0o755,
            "st_nlink": 2,
            "st_uid": os.getuid(),
            "st_gid": os.getgid(),
            "st_size": 0,
            "st_atime": self._now,
            "st_mtime": self._now,
            "st_ctime": self._now,
        }

    def _file_stat(self, size: int) -> dict:
        return {
            "st_mode": stat.S_IFREG | 0o644,
            "st_nlink": 1,
            "st_uid": os.getuid(),
            "st_gid": os.getgid(),
            "st_size": size,
            "st_atime": self._now,
            "st_mtime": self._now,
            "st_ctime": self._now,
        }

    def _is_virtual_dir(self, path: str) -> bool:
        normalized = path.rstrip("/") + "/"
        for p in self._prefixes:
            if p.startswith(normalized) or p.rstrip("/") == path.rstrip("/"):
                return True
        return False

    def getattr(self, path: str, fh=None) -> dict:
        if path == "/":
            return self._dir_stat()
        if path == _MIRAGE_DIR:
            return self._dir_stat()
        if path == _MIRAGE_WHOAMI:
            return self._file_stat(len(self._whoami_content()))
        if self._is_virtual_dir(path):
            return self._dir_stat()
        try:
            s = self.ws.stat(path)
            return self._file_stat(s.size or 0)
        except (FileNotFoundError, ValueError):
            pass
        try:
            self.ws.ls(path)
            return self._dir_stat()
        except (FileNotFoundError, ValueError):
            raise fuse.FuseOSError(errno.ENOENT)

    def _virtual_children(self, path: str) -> list[str]:
        normalized = path.rstrip("/") + "/" if path != "/" else "/"
        children = set()
        for p in self._prefixes:
            if p.startswith(normalized) and p != normalized:
                rest = p[len(normalized):]
                child = rest.split("/")[0]
                if child:
                    children.add(child)
        return sorted(children)

    def _clean_path(self, path: str) -> str:
        basename = os.path.basename(path)
        if basename.startswith("._"):
            basename = basename[2:]
            return os.path.join(os.path.dirname(path), basename)
        return path

    def _record_op(self, op: str, path: str, raw: str) -> None:
        path = self._clean_path(path)
        with self._ops_lock:
            self._ops.append({
                "type":
                "fuse_op",
                "op":
                op,
                "path":
                path,
                "timestamp":
                datetime.now(timezone.utc).isoformat(),
                "raw":
                raw,
            })

    def drain_ops(self) -> list[dict]:
        with self._ops_lock:
            ops = list(self._ops)
            self._ops.clear()
            self._read_seen.clear()
            return ops

    def readdir(self, path: str, fh) -> list:
        if path == _MIRAGE_DIR:
            return [".", "..", "whoami"]
        names = set(self._virtual_children(path))
        if path == "/":
            names.add(".mirage")
        try:
            entries = self.ws.ls(path)
            for e in entries:
                part = e.rstrip("/").rsplit("/", 1)[-1]
                if part:
                    names.add(part)
        except (FileNotFoundError, ValueError):
            if not names:
                raise fuse.FuseOSError(errno.ENOENT)
        return [".", ".."] + sorted(names)

    def _record_read(self, path: str) -> None:
        clean = self._clean_path(path)
        with self._ops_lock:
            if clean not in self._read_seen:
                self._read_seen.add(clean)
                self._ops.append({
                    "type":
                    "fuse_op",
                    "op":
                    "read",
                    "path":
                    clean,
                    "timestamp":
                    datetime.now(timezone.utc).isoformat(),
                    "raw":
                    f"read {clean}",
                })

    def read(self, path: str, size: int, offset: int, fh) -> bytes:
        if path == _MIRAGE_WHOAMI:
            data = self._whoami_content()
            return data[offset:offset + size]
        op = self._handle_ops.get(fh)
        ctx = self._handles.get(fh)
        if op is None or ctx is None:
            try:
                data = self.ws.cat(path)
                self._record_read(path)
                return data[offset:offset + size]
            except (FileNotFoundError, ValueError):
                raise fuse.FuseOSError(errno.ENOENT)
        try:
            data = op.read(self.ws, path, offset, size, ctx)
            self._record_read(path)
            return data
        except (FileNotFoundError, ValueError):
            raise fuse.FuseOSError(errno.ENOENT)

    def write(self, path: str, data: bytes, offset: int, fh) -> int:
        op = self._handle_ops.get(fh)
        ctx = self._handles.get(fh)
        if op is not None and ctx is not None:
            try:
                result = op.write(self.ws, path, offset, data, ctx)
                self._record_op("write", path, f"write {path}")
                return result
            except PermissionError:
                raise fuse.FuseOSError(errno.EACCES)
        try:
            existing = b""
            try:
                existing = self.ws.cat(path)
            except FileNotFoundError:
                pass
            if offset > len(existing):
                existing = existing + b"\0" * (offset - len(existing))
            new_data = existing[:offset] + data + existing[offset + len(data):]
            self.ws.write(path, new_data)
            self._record_op("write", path, f"write {path}")
            return len(data)
        except PermissionError:
            raise fuse.FuseOSError(errno.EACCES)
        except ValueError:
            raise fuse.FuseOSError(errno.ENOENT)

    def create(self, path: str, mode, fi=None) -> int:
        try:
            self.ws.write(path, b"")
            self._record_op("create", path, f"create {path}")
            op = self._fuse_registry.resolve(path, 0, self.ws)
            ctx = op.on_open(self.ws, path, 0)
            ctx["path"] = path
            fh = self._next_fh
            self._next_fh += 1
            self._handles[fh] = ctx
            self._handle_ops[fh] = op
            return fh
        except PermissionError:
            raise fuse.FuseOSError(errno.EACCES)
        except ValueError:
            raise fuse.FuseOSError(errno.ENOENT)

    def mkdir(self, path: str, mode) -> None:
        try:
            self.ws.mkdir(path)
            self._record_op("mkdir", path, f"mkdir {path}")
        except PermissionError:
            raise fuse.FuseOSError(errno.EACCES)
        except ValueError:
            raise fuse.FuseOSError(errno.ENOENT)

    def unlink(self, path: str) -> None:
        try:
            self.ws.rm(path)
            self._record_op("rm", path, f"rm {path}")
        except PermissionError:
            raise fuse.FuseOSError(errno.EACCES)
        except FileNotFoundError:
            raise fuse.FuseOSError(errno.ENOENT)

    def rename(self, old: str, new: str, flags: int = 0) -> None:
        try:
            self.ws.mv(old, new)
            self._record_op("mv", old, f"mv {old} → {new}")
        except PermissionError:
            raise fuse.FuseOSError(errno.EACCES)
        except (FileNotFoundError, ValueError):
            raise fuse.FuseOSError(errno.ENOENT)

    def rmdir(self, path: str) -> None:
        try:
            entries = self.ws.ls(path)
            if entries:
                raise fuse.FuseOSError(errno.ENOTEMPTY)
            self._record_op("rmdir", path, f"rmdir {path}")
        except (FileNotFoundError, ValueError):
            raise fuse.FuseOSError(errno.ENOENT)

    def statfs(self, path: str) -> dict:
        return {
            "f_bsize": 4096,
            "f_frsize": 4096,
            "f_blocks": 1024 * 1024,
            "f_bfree": 1024 * 1024,
            "f_bavail": 1024 * 1024,
            "f_files": 1000000,
            "f_ffree": 1000000,
            "f_favail": 1000000,
            "f_namemax": 255,
        }

    def chmod(self, path: str, mode) -> None:
        self.getattr(path)

    def chown(self, path: str, uid: int, gid: int) -> None:
        self.getattr(path)

    def utimens(self, path: str, times=None) -> None:
        self.getattr(path)

    def access(self, path: str, amode: int) -> None:
        self.getattr(path)

    def flush(self, path: str, fh) -> None:
        op = self._handle_ops.get(fh)
        ctx = self._handles.get(fh)
        if op is not None and ctx is not None:
            try:
                op.on_flush(self.ws, path, ctx)
            except PermissionError:
                raise fuse.FuseOSError(errno.EACCES)
            return
        self.ws.sync(path)

    def fsync(self, path: str, datasync: int, fh) -> None:
        self.flush(path, fh)

    def open(self, path: str, flags) -> int:
        if path == _MIRAGE_WHOAMI:
            fh = self._next_fh
            self._next_fh += 1
            self._handles[fh] = {"path": path}
            return fh
        try:
            s = self.ws.stat(path)
            size = s.size or 0
        except (FileNotFoundError, ValueError):
            raise fuse.FuseOSError(errno.ENOENT)
        op = self._fuse_registry.resolve(path, size, self.ws)
        ctx = op.on_open(self.ws, path, size)
        ctx["path"] = path
        fh = self._next_fh
        self._next_fh += 1
        self._handles[fh] = ctx
        self._handle_ops[fh] = op
        return fh

    def release(self, path: str, fh) -> int:
        self._handles.pop(fh, None)
        self._handle_ops.pop(fh, None)
        return 0

    def truncate(self, path: str, length: int, fh=None) -> None:
        try:
            data = b""
            try:
                data = self.ws.cat(path)
            except FileNotFoundError:
                pass
            padded = data[:length].ljust(length, b"\0")
            self.ws.write(path, padded)
        except PermissionError:
            raise fuse.FuseOSError(errno.EACCES)
        except ValueError:
            raise fuse.FuseOSError(errno.ENOENT)


def _run_fuse(fs: MirageFS, mountpoint: str, foreground: bool) -> None:
    fuse.FUSE(fs, mountpoint, nothreads=True, foreground=foreground)


def mount_background(ws: Workspace,
                     mountpoint: str,
                     agent_id: str | None = None) -> threading.Thread:
    """Start FUSE in a daemon thread and return immediately."""
    fs = MirageFS(ws, agent_id=agent_id)
    t = threading.Thread(target=_run_fuse,
                         args=(fs, mountpoint, True),
                         daemon=True)
    t.start()
    time.sleep(0.3)
    return t


def mount(ws: Workspace | None = None,
          mountpoint: str = "",
          foreground: bool = True,
          agent_id: str | None = None,
          fs: MirageFS | None = None) -> None:
    if fs is None:
        fs = MirageFS(ws, agent_id=agent_id)
    t = threading.Thread(
        target=_run_fuse,
        args=(fs, mountpoint, foreground),
        daemon=True,
    )
    t.start()
    try:
        while t.is_alive():
            t.join(timeout=0.5)
    except KeyboardInterrupt:
        print("\nUnmounting...", flush=True)
        if sys.platform == "darwin":
            subprocess.run(
                ["diskutil", "unmount", "force", mountpoint],
                capture_output=True,
            )
        else:
            subprocess.run(["fusermount", "-u", mountpoint],
                           capture_output=True)
        t.join(timeout=5)

