import base64

from fastapi import APIRouter, HTTPException, Request

from mirage.server import routes
from mirage.server.fastapi.config import (PathRequest, ReaddirRequest,
                                          ReadRequest, RenameRequest,
                                          TruncateRequest, WriteRequest)

io_router = APIRouter(tags=["io"])


def _get_service(request: Request):
    return request.app.state.service


@io_router.post(routes.IO_READ)
def io_read(ws_id: str, req: ReadRequest, request: Request) -> dict:
    svc = _get_service(request)
    try:
        data = svc.io_read(ws_id, req.path, req.offset, req.size)
    except KeyError:
        raise HTTPException(status_code=404, detail="workspace not found")
    except FileNotFoundError:
        raise HTTPException(status_code=404, detail="file not found")
    return {"data": base64.b64encode(data).decode()}


@io_router.post(routes.IO_WRITE)
def io_write(ws_id: str, req: WriteRequest, request: Request) -> dict:
    svc = _get_service(request)
    try:
        raw = base64.b64decode(req.data)
        written = svc.io_write(ws_id, req.path, req.offset, raw)
    except KeyError:
        raise HTTPException(status_code=404, detail="workspace not found")
    except FileNotFoundError:
        raise HTTPException(status_code=404, detail="file not found")
    return {"written": written}


@io_router.post(routes.IO_STAT)
def io_stat(ws_id: str, req: PathRequest, request: Request) -> dict:
    svc = _get_service(request)
    try:
        st = svc.io_stat(ws_id, req.path)
    except KeyError:
        raise HTTPException(status_code=404, detail="workspace not found")
    except FileNotFoundError:
        raise HTTPException(status_code=404, detail="file not found")
    return st.model_dump()


@io_router.post(routes.IO_READDIR)
def io_readdir(ws_id: str, req: ReaddirRequest, request: Request) -> dict:
    svc = _get_service(request)
    try:
        entries, cursor = svc.io_readdir(ws_id, req.path, req.cursor)
    except KeyError:
        raise HTTPException(status_code=404, detail="workspace not found")
    return {"entries": entries, "cursor": cursor}


@io_router.post(routes.IO_CREATE)
def io_create(ws_id: str, req: PathRequest, request: Request) -> dict:
    svc = _get_service(request)
    try:
        svc.io_create(ws_id, req.path)
    except KeyError:
        raise HTTPException(status_code=404, detail="workspace not found")
    return {"ok": True}


