from fastapi import FastAPI, HTTPException, Request
from pydantic import BaseModel

from mirage.commands.custom.registry import CommandRegistry, ExternalCommand
from mirage.commands.remote.auth import AuthError, NoAuth, ServerAuth
from mirage.workspace import Workspace

command_server_app = FastAPI()


def configure(ws: Workspace,
              auth: ServerAuth = NoAuth(),
              registry: CommandRegistry | None = None) -> None:
    command_server_app.state.workspace = ws
    command_server_app.state.auth = auth
    command_server_app.state.registry = registry or CommandRegistry()


def _verify_request(request: Request) -> None:
    headers = {k.lower(): v for k, v in request.headers.items()}
