import os
import resource
import time
from typing import TYPE_CHECKING, Any

from mirage.backend.local.memory import MemoryBackend
from mirage.commands import COMMAND_COST, COMMANDS
from mirage.types import CostLevel

if TYPE_CHECKING:
    from mirage.workspace import Workspace

_server_start_time: float = 0.0


def _count_dirty(ws: "Workspace") -> int:
    memory_mounts = {
        m.prefix
        for m in ws._registry.mounts() if isinstance(m.backend, MemoryBackend)
    }
    return len([
        i for i in ws._tracker.dirty() if i.backend_mount not in memory_mounts
    ])


def set_server_start_time(t: float) -> None:
    global _server_start_time
    _server_start_time = t


def global_status(sessions: dict[str, Any]) -> dict:
    rss = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    if os.uname().sysname == "Darwin":
        rss_bytes = rss
    else:
        rss_bytes = rss * 1024
    total_cache = 0
    for s in sessions.values():
        if s.ws is not None:
            total_cache += s.ws._cache.size
    uptime_s = int(time.monotonic() - _server_start_time)
    return {
        "rss_bytes": rss_bytes,
        "total_sessions": len(sessions),
        "total_cache_bytes": total_cache,
        "uptime_seconds": uptime_s,
    }


def list_sessions(sessions: dict[str, Any]) -> list[dict]:
    results = []
    for s in sessions.values():
        entry: dict[str, Any] = {
            "id": s.id,
            "fuse_mounted": s.fuse_mounted,
            "mode": s.mode,
            "mounts": s.mounts,
        }
        if s.ws is not None:
            entry["cache_used"] = s.ws._cache.size
            entry["cache_limit"] = s.ws._cache.limit
            entry["dirty_count"] = len(s.ws._tracker.dirty())
            entry["total_commands"] = s.command_stats.total_commands
        results.append(entry)
    return results


def workspace_status(session: Any) -> dict:
    ws: Workspace = session.ws
    backends_health = []
    for mount in ws._registry.mounts():
        backends_health.append({
            "mount": mount.prefix,
            "backend": type(mount.backend).__name__,
        })
    return {
        "cache_used": ws._cache.size,
        "cache_limit": ws._cache.limit,
        "dirty_inodes": _count_dirty(ws),
        "backends": backends_health,
        "last_command": session.command_stats.last_command,
        "total_commands": session.command_stats.total_commands,
        "total_errors": session.command_stats.total_errors,
    }


def workspace_commands(session: Any) -> list[dict]:
    result = []
    for name in sorted(COMMANDS.keys()):
        cost = COMMAND_COST.get(name, CostLevel.CHEAP)
        result.append({
            "name": name,
            "source": "builtin",
            "cost_level": cost.value,
        })
    for name, ext in session.registry._external.items():
        result.append({
            "name": name,
            "source": "external",
            "cost_level": "unknown",
            "description": ext.description,
            "exec": ext.exec,
        })
    return result


def workspace_memory(session: Any) -> dict:
    ws: Workspace = session.ws
    cache_entries = {}
    for path, entry in ws._cache._store.items():
        cache_entries[path] = len(entry.data)
    dirty_paths = [i.virtual_path for i in ws._tracker.dirty()]
    backend_memory: dict[str, dict] = {}
    for mount in ws._registry.mounts():
        if isinstance(mount.backend, MemoryBackend):
            total = sum(len(v) for v in mount.backend._files.values())
            backend_memory[mount.prefix] = {
                "type": "MemoryBackend",
                "file_count": len(mount.backend._files),
                "total_bytes": total,
            }
    return {
        "cache": {
            "used": ws._cache.size,
            "limit": ws._cache.limit,
            "entry_count": len(ws._cache._store),
            "entries": cache_entries,
        },
        "dirty_tracker": {
            "total_inodes": len(ws._tracker._inodes),
            "dirty_paths": dirty_paths,
        },
        "backend_memory": backend_memory,
    }


def workspace_transfers(session: Any) -> dict:
    ws: Workspace = session.ws
    return workspace_transfers_from_ws(ws)


def workspace_status_from_ws(ws: "Workspace") -> dict:
    backends_health = []
    for mount in ws._registry.mounts():
        backends_health.append({
            "mount": mount.prefix,
            "backend": type(mount.backend).__name__,
        })
    return {
        "cache_used": ws._cache.size,
        "cache_limit": ws._cache.limit,
        "dirty_inodes": _count_dirty(ws),
        "backends": backends_health,
        "last_command": None,
        "total_commands": 0,
        "total_errors": 0,
    }


def workspace_transfers_from_ws(ws: "Workspace") -> dict:
    per_backend: dict[str, dict] = {}
    for prefix, stats in ws._transfer_stats.items():
        total_reads = stats.read_ops
        avg_read_ms = (stats.total_read_ms /
                       total_reads if total_reads > 0 else 0)
        total_cache_ops = stats.cache_hits + stats.cache_misses
        hit_rate = (stats.cache_hits /
                    total_cache_ops if total_cache_ops > 0 else 0.0)
        per_backend[prefix] = {
            "bytes_read": stats.bytes_read,
            "bytes_written": stats.bytes_written,
            "read_ops": stats.read_ops,
            "write_ops": stats.write_ops,
            "avg_read_latency_ms": round(avg_read_ms, 1),
            "cache_hit_rate": round(hit_rate, 3),
        }
    return per_backend

