    s = limit.strip().upper()
    for suffix, mult in [("GB", 1 << 30), ("MB", 1 << 20), ("KB", 1 << 10)]:
        if s.endswith(suffix):
            return int(s[:-len(suffix)]) * mult
    return int(s)


