import os

import yaml

from mirage.backend.base import BaseBackend
from mirage.backend.local.local import LocalBackend
from mirage.backend.local.memory import MemoryBackend
from mirage.types import BackendType, MountMode
from mirage.workspace.consistency import ConsistencyPolicy


def _build_backend(type_name: str, connection: str) -> BaseBackend:
    if type_name == BackendType.MEMORY:
        return MemoryBackend()
    if type_name == BackendType.LOCAL:
        return LocalBackend(root=os.path.abspath(connection))
    if type_name == BackendType.S3:
        from mirage.backend.object_storage.s3 import S3Backend, S3Config
        rest = connection[len("s3://"):]
        bucket = rest.split("/", 1)[0]
        return S3Backend(S3Config(bucket=bucket))
    if type_name == BackendType.R2:
        from mirage.backend.object_storage.r2 import R2Backend, R2Config
        rest = connection[len("r2://"):]
        parts = rest.split("/", 1)
        return R2Backend(
            R2Config(
                account_id=parts[0],
                bucket=parts[1] if len(parts) > 1 else "",
                access_key_id=os.environ.get("R2_ACCESS_KEY_ID", ""),
                secret_access_key=os.environ.get("R2_SECRET_ACCESS_KEY", ""),
            ))
    if type_name in (BackendType.HTTP, BackendType.HTTPS):
        from mirage.backend.network.http import HTTPBackend, HTTPConfig
        return HTTPBackend(HTTPConfig(base_url=connection))
    raise ValueError(f"Unknown backend type: {type_name!r}. "
                     "Use built-ins: memory, local, s3, r2, http")


def parse_mount_uri(uri: str) -> BaseBackend:
    if uri == BackendType.MEMORY:
        return MemoryBackend()
    if uri == BackendType.LOCAL:
        return LocalBackend(root=os.path.abspath("."))

    colon = uri.find(":")
    if colon > 0 and "//" not in uri[:colon + 3]:
        return _build_backend(uri[:colon], uri[colon + 1:])

    if uri.startswith("s3://"):
        return _build_backend("s3", uri)
    if uri.startswith("r2://"):
        return _build_backend("r2", uri)
    if uri.startswith("http://") or uri.startswith("https://"):
        return _build_backend("http", uri)

    if "://" in uri:
        scheme = uri.split("://")[0]
        raise ValueError(
            f"Unknown URI scheme {scheme!r}. "
            "Accepted: s3://, r2://, https://. "
            "For simple backends use: memory, local, local:./path")
    return LocalBackend(root=os.path.abspath(uri))


def split_mount_spec(spec: str) -> tuple[str, str]:
    """Split 'backend:/path' into (backend, path).

    Args:
        spec (str): Mount spec like 'memory:/data/' or 's3://bucket:/data/'.

    Returns:
        tuple[str, str]: (backend, mount_path) pair.
    """
    i = len(spec) - 1
    while i >= 0:
        if spec[i] == ":" and i + 1 < len(spec) and spec[i + 1] == "/":
            if i >= 2 and spec[i - 1:i + 2] == "://":
                i -= 1
                continue
            return spec[:i], spec[i + 1:]
        i -= 1
    raise ValueError(
        f"Invalid mount spec: {spec!r}. "
        "Use format: backend:/path (e.g. memory:/data/, s3://bucket:/)")


_MODE_SUFFIXES = ("@read", "@write", "@exec")


def parse_mount_uri_with_mode(
    uri: str,
    default_mode: MountMode = MountMode.READ,
) -> tuple[BaseBackend, MountMode]:
    for suffix in _MODE_SUFFIXES:
        if uri.endswith(suffix):
            return parse_mount_uri(uri[:-len(suffix)]), MountMode(suffix[1:])
    return parse_mount_uri(uri), default_mode


_CONSISTENCY_SUFFIXES = ("#cached", "#lazy", "#ttl", "#always")


def parse_mount_uri_full(
    uri: str,
    default_mode: MountMode = MountMode.READ,
    default_consistency: ConsistencyPolicy = ConsistencyPolicy.CACHED,
) -> tuple[BaseBackend, MountMode, ConsistencyPolicy]:
    consistency = default_consistency
    for suffix in _CONSISTENCY_SUFFIXES:
        if uri.endswith(suffix):
            consistency = ConsistencyPolicy(suffix[1:])
            uri = uri[:-len(suffix)]
            break
    backend, mode = parse_mount_uri_with_mode(uri, default_mode)
    return backend, mode, consistency


def parse_mounts_from_cli(
    mount_specs: list[str],
    default_mode: MountMode = MountMode.READ,
) -> dict[str, BaseBackend | tuple[BaseBackend, MountMode]]:
    mounts: dict[str, BaseBackend | tuple[BaseBackend, MountMode]] = {}
    for spec in mount_specs:
        uri, prefix = split_mount_spec(spec)
        backend, mode = parse_mount_uri_with_mode(uri, default_mode)
        if mode != default_mode:
            mounts[prefix] = (backend, mode)
        else:
            mounts[prefix] = backend
    return mounts


def load_yaml_config(path: str) -> dict:
    with open(path) as f:
        return yaml.safe_load(f)


def load_workspace_yaml(path: str) -> dict:
    with open(path) as f:
        data = yaml.safe_load(f)
    mounts_raw = data.get("mounts", {})
    mounts: dict[str, str | dict] = {}
    for prefix, value in mounts_raw.items():
        if isinstance(value, str):
            mounts[prefix] = value
        elif isinstance(value, dict):
            backend_spec = value.get("backend")
            if backend_spec:
                entry: dict[str, str | dict] = {"backend": backend_spec}
                if value.get("args"):
                    entry["args"] = value["args"]
                if value.get("mode"):
                    entry["mode"] = value["mode"]
                if value.get("consistency"):
                    entry["consistency"] = value["consistency"]
                mounts[prefix] = entry
            else:
                uri = value.get("uri", "")
                mount_mode = value.get("mode")
                mount_consistency = value.get("consistency")
                entry_uri: dict[str, str] = {"uri": uri}
                if mount_mode:
                    entry_uri["mode"] = mount_mode
                if mount_consistency:
                    entry_uri["consistency"] = mount_consistency
                if len(entry_uri) == 1:
                    mounts[prefix] = uri
                else:
                    mounts[prefix] = entry_uri
    result: dict = {"mounts": mounts, "commands": data.get("commands", {})}
    if "consistency" in data:
        result["consistency"] = data["consistency"]
    if "ttl" in data:
        result["ttl"] = data["ttl"]
    if "agent_id" in data:
        result["agent_id"] = data["agent_id"]
    fuse_ops = data.get("fuse_ops", {})
    if fuse_ops:
        result["fuse_ops"] = fuse_ops
    for key in ("runtime", "url", "ws_id", "command_url", "fuse_ops_url"):
        if key in data:
            result[key] = data[key]
    return result

import posixpath
from typing import Callable

from mirage.types import CostLevel
from mirage.workspace import Workspace

from . import nav, net, read, search, write


def _resolve(cwd: str, path: str) -> str:
    if path.startswith("/"):
        return path
    return posixpath.normpath(posixpath.join(cwd, path))


def _check_flags(cmd: str, argv: list[str], allowed: set[str]) -> None:
    for a in argv:
        if not a.startswith("-") or a in (">", ">>", "--"):
            continue
        if a.startswith("--"):
            if a not in allowed:
                raise ValueError(f"{cmd}: unrecognized option '{a}'")
            continue
        if a in allowed:
            continue
        for ch in a[1:]:
            if not ch.isalpha():
                break
            if f"-{ch}" not in allowed:
                raise ValueError(f"{cmd}: invalid option -- '{ch}'")


def _ls(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("ls", argv,
                 {"-l", "-a", "-A", "-h", "-t", "-S", "-r", "-1", "-R", "-d"})
    long = any(
        a.startswith("-") and not a.startswith("--") and "l" in a
        for a in argv)
    all_files = any(
        a.startswith("-") and not a.startswith("--") and ("a" in a or "A" in a)
        for a in argv)
    human_readable = any(
        a.startswith("-") and not a.startswith("--") and "h" in a
        for a in argv)
    reverse = any(
        a.startswith("-") and not a.startswith("--") and "r" in a
        for a in argv)
    recursive = any(
        a.startswith("-") and not a.startswith("--") and "R" in a
        for a in argv)
    list_dir = any(
        a.startswith("-") and not a.startswith("--") and "d" in a
        for a in argv)
    sort_by = "name"
    for a in argv:
        if a.startswith("-") and not a.startswith("--"):
            if "t" in a:
                sort_by = "time"
            elif "S" in a:
                sort_by = "size"
    paths = [a for a in argv if not a.startswith("-")] or [cwd]
    results: list[str] = []
    for p in paths:
        entries = nav.ls(ws,
                         _resolve(cwd, p),
                         long=long,
                         all_files=all_files,
                         sort_by=sort_by,
                         reverse=reverse,
                         human_readable=human_readable,
                         recursive=recursive,
                         list_dir=list_dir)
        if long:
            for e in entries:
                size_str = nav._human_size(
                    e.size or 0) if human_readable else str(e.size or 0)
                line = (f"{e.type or '-'}\t{size_str}"
                        f"\t{e.modified or ''}\t{e.name}")
                results.append(line)
        else:
            results.extend(e.name for e in entries)
    return "\n".join(results)


def _stat(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("stat", argv, set())
    paths = [a for a in argv if not a.startswith("-")]
    if not paths:
        raise ValueError("stat: missing operand")
    s = nav.stat(ws, _resolve(cwd, paths[0]))
    return f"name={s.name} size={s.size} modified={s.modified} type={s.type}"


def _pwd(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("pwd", argv, set())
    return nav.pwd(cwd)


def _find(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("find", argv, {"-name", "-type", "-maxdepth", "-size"})
    name = None
    ftype = None
    maxdepth = None
    paths = []
    i = 0
    while i < len(argv):
        if argv[i] == "-name" and i + 1 < len(argv):
            name = argv[i + 1]
            i += 2
        elif argv[i] == "-type" and i + 1 < len(argv):
            raw = argv[i + 1]
            if raw == "d":
                ftype = "directory"
            elif raw == "f":
                ftype = "file"
            else:
                ftype = raw
            i += 2
        elif argv[i] == "-maxdepth" and i + 1 < len(argv):
            maxdepth = int(argv[i + 1])
            i += 2
        elif argv[i].startswith("-"):
            i += 1
        else:
            paths.append(argv[i])
            i += 1
    path = _resolve(cwd, paths[0]) if paths else cwd
    return "\n".join(
        nav.find(ws, path, name=name, type=ftype, maxdepth=maxdepth))


def _tree(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("tree", argv, set())
    paths = [a for a in argv if not a.startswith("-")]
    path = _resolve(cwd, paths[0]) if paths else cwd
    return "\n".join(nav.tree(ws, path))


def _du(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("du", argv, {"-h", "-s", "-a"})
    human_readable = any(
        a.startswith("-") and not a.startswith("--") and "h" in a
        for a in argv)
    paths = [a for a in argv if not a.startswith("-")]
    path = _resolve(cwd, paths[0]) if paths else cwd
    total = nav.du(ws, path)
    return nav._human_size(total) if human_readable else str(total)


def _cat(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("cat", argv, set())
    paths = [a for a in argv if not a.startswith("-")]
    if not paths:
        raise ValueError("cat: missing operand")
    return read.cat(ws, _resolve(cwd, paths[0])).decode(errors="replace")


def _head(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("head", argv, {"-n", "-c"})
    n = 10
    bytes_mode = None
    paths = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-n" and i + 1 < len(argv):
            n = int(argv[i + 1])
            i += 2
        elif a.startswith("-n") and len(a) > 2 and a[2:].isdigit():
            n = int(a[2:])
            i += 1
        elif a == "-c" and i + 1 < len(argv):
            bytes_mode = int(argv[i + 1])
            i += 2
        elif a.startswith("-c") and len(a) > 2 and a[2:].isdigit():
            bytes_mode = int(a[2:])
            i += 1
        elif not a.startswith("-"):
            paths.append(a)
            i += 1
        else:
            i += 1
    if not paths:
        raise ValueError("head: missing operand")
    return read.head(ws,
                     _resolve(cwd, paths[0]),
                     lines=n,
                     bytes_mode=bytes_mode).decode(errors="replace")


def _tail(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("tail", argv, {"-n", "-c"})
    n = 10
    bytes_mode = None
    paths = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-n" and i + 1 < len(argv):
            n = int(argv[i + 1])
            i += 2
        elif a.startswith("-n") and len(a) > 2 and a[2:].isdigit():
            n = int(a[2:])
            i += 1
        elif a == "-c" and i + 1 < len(argv):
            bytes_mode = int(argv[i + 1])
            i += 2
        elif a.startswith("-c") and len(a) > 2 and a[2:].isdigit():
            bytes_mode = int(a[2:])
            i += 1
        elif not a.startswith("-"):
            paths.append(a)
            i += 1
        else:
            i += 1
    if not paths:
        raise ValueError("tail: missing operand")
    return read.tail(ws,
                     _resolve(cwd, paths[0]),
                     lines=n,
                     bytes_mode=bytes_mode).decode(errors="replace")


def _wc(ws: Workspace, argv: list[str], cwd: str) -> str:
    # NOTE: downloads full file; no streaming optimization available
    _check_flags("wc", argv, {"-l", "-w", "-c", "-m"})
    lines_only = any(
        a.startswith("-") and not a.startswith("--") and "l" in a
        for a in argv)
    words_only = any(
        a.startswith("-") and not a.startswith("--") and "w" in a
        for a in argv)
    bytes_only = any(
        a.startswith("-") and not a.startswith("--") and ("c" in a or "m" in a)
        for a in argv)
    paths = [a for a in argv if not a.startswith("-")]
    if not paths:
        raise ValueError("wc: missing operand")
    result = read.wc(ws,
                     _resolve(cwd, paths[0]),
                     lines_only=lines_only,
                     words_only=words_only,
                     bytes_only=bytes_only)
    if isinstance(result, int):
        return str(result)
    return f"{result['lines']}\t{result['words']}\t{result['bytes']}"


def _md5(ws: Workspace, argv: list[str], cwd: str) -> str:
    # NOTE: downloads full file; no streaming optimization available
    _check_flags("md5", argv, set())
    paths = [a for a in argv if not a.startswith("-")]
    if not paths:
        raise ValueError("md5: missing operand")
    return read.md5(ws, _resolve(cwd, paths[0]))


def _diff(ws: Workspace, argv: list[str], cwd: str) -> str:
    # NOTE: downloads full files; S3 Select could help for pattern matching
    _check_flags("diff", argv, set())
    paths = [a for a in argv if not a.startswith("-")]
    if len(paths) < 2:
        raise ValueError("diff: requires two paths")
    return "".join(
        read.diff(ws, _resolve(cwd, paths[0]), _resolve(cwd, paths[1])))


def _file(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("file", argv, set())
    paths = [a for a in argv if not a.startswith("-")]
    if not paths:
        raise ValueError("file: missing operand")
    return read.file(ws, _resolve(cwd, paths[0]))


def _grep(ws: Workspace, argv: list[str], cwd: str) -> str:
    # ws.grep() uses S3 Select on S3/R2 for files >1MB; full download otherwise
    _check_flags("grep", argv, {
        "-r", "-R", "-i", "-v", "-n", "-c", "-l", "-w", "-F", "-E", "-o", "-m"
    })
    recursive = False
    ignore_case = False
    invert = False
    line_numbers = False
    count_only = False
    files_only = False
    whole_word = False
    fixed_string = False
    only_matching = False
    max_count = None
    pos = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-m" and i + 1 < len(argv):
            max_count = int(argv[i + 1])
            i += 2
        elif a.startswith("-m") and len(a) > 2 and a[2:].isdigit():
            max_count = int(a[2:])
            i += 1
        elif a.startswith("-") and not a.startswith("--"):
            if "r" in a or "R" in a:
                recursive = True
            if "i" in a:
                ignore_case = True
            if "v" in a:
                invert = True
            if "n" in a:
                line_numbers = True
            if "c" in a:
                count_only = True
            if "l" in a:
                files_only = True
            if "w" in a:
                whole_word = True
            if "F" in a:
                fixed_string = True
            if "o" in a:
                only_matching = True
            i += 1
        elif not a.startswith("-"):
            pos.append(a)
            i += 1
        else:
            i += 1
    if len(pos) < 2:
        raise ValueError("grep: usage: grep [flags] pattern path")
    pattern, path = pos[0], _resolve(cwd, pos[1])
    return "\n".join(
        search.grep(ws,
                    pattern,
                    path,
                    recursive=recursive,
                    ignore_case=ignore_case,
                    invert=invert,
                    line_numbers=line_numbers,
                    count_only=count_only,
                    files_only=files_only,
                    fixed_string=fixed_string,
                    only_matching=only_matching,
                    max_count=max_count,
                    whole_word=whole_word))


def _sort(ws: Workspace, argv: list[str], cwd: str) -> str:
    # NOTE: downloads full file to sort in memory
    _check_flags("sort", argv, {"-r", "-n", "-k", "-t", "-u", "-f"})
    reverse = False
    numeric = False
    key_field = None
    field_sep = None
    unique = False
    ignore_case = False
    paths = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-k" and i + 1 < len(argv):
            key_field = int(argv[i + 1])
            i += 2
        elif a.startswith("-k") and len(a) > 2 and a[2:].isdigit():
            key_field = int(a[2:])
            i += 1
        elif a == "-t" and i + 1 < len(argv):
            field_sep = argv[i + 1]
            i += 2
        elif a.startswith("-t") and len(a) > 2:
            field_sep = a[2:]
            i += 1
        elif a.startswith("-") and not a.startswith("--"):
            if "r" in a:
                reverse = True
            if "n" in a:
                numeric = True
            if "u" in a:
                unique = True
            if "f" in a:
                ignore_case = True
            i += 1
        elif not a.startswith("-"):
            paths.append(a)
            i += 1
        else:
            i += 1
    if not paths:
        raise ValueError("sort: missing operand")
    return "\n".join(
        search.sort_lines(ws,
                          _resolve(cwd, paths[0]),
                          reverse=reverse,
                          numeric=numeric,
                          key_field=key_field,
                          field_sep=field_sep,
                          unique=unique,
                          ignore_case=ignore_case))


def _uniq(ws: Workspace, argv: list[str], cwd: str) -> str:
    # NOTE: downloads full file to process in memory
    _check_flags("uniq", argv, {"-c", "-d", "-u"})
    count = any(
        a.startswith("-") and not a.startswith("--") and "c" in a
        for a in argv)
    duplicates_only = any(
        a.startswith("-") and not a.startswith("--") and "d" in a
        for a in argv)
    unique_only = any(
        a.startswith("-") and not a.startswith("--") and "u" in a
        for a in argv)
    paths = [a for a in argv if not a.startswith("-")]
    if not paths:
        raise ValueError("uniq: missing operand")
    return "\n".join(
        search.uniq(ws,
                    _resolve(cwd, paths[0]),
                    count=count,
                    duplicates_only=duplicates_only,
                    unique_only=unique_only))


def _cut(ws: Workspace, argv: list[str], cwd: str) -> str:
    # NOTE: downloads full file to process in memory
    _check_flags("cut", argv, {"-f", "-d", "-c"})
    fields = None
    delim = "\t"
    chars = None
    paths = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-f" and i + 1 < len(argv):
            fields = [int(x) for x in argv[i + 1].split(",")]
            i += 2
        elif a.startswith("-f") and len(a) > 2:
            fields = [int(x) for x in a[2:].split(",")]
            i += 1
        elif a == "-d" and i + 1 < len(argv):
            delim = argv[i + 1]
            i += 2
        elif a.startswith("-d") and len(a) > 2:
            delim = a[2:]
            i += 1
        elif a == "-c" and i + 1 < len(argv):
            chars = _parse_char_ranges(argv[i + 1])
            i += 2
        elif a.startswith("-c") and len(a) > 2:
            chars = _parse_char_ranges(a[2:])
            i += 1
        elif not a.startswith("-"):
            paths.append(a)
            i += 1
        else:
            i += 1
    if not paths:
        raise ValueError("cut: missing operand")
    return "\n".join(
        search.cut(ws,
                   _resolve(cwd, paths[0]),
                   delimiter=delim,
                   fields=fields,
                   chars=chars))


def _parse_char_ranges(spec: str) -> list[tuple[int, int]]:
    ranges = []
    for part in spec.split(","):
        if "-" in part:
            lo, hi = part.split("-", 1)
            ranges.append((int(lo), int(hi)))
        else:
            n = int(part)
            ranges.append((n, n))
    return ranges


def _tr(ws: Workspace, argv: list[str], cwd: str) -> str:
    # NOTE: downloads full file to process in memory
    pos = [a for a in argv if not a.startswith("-")]
    if len(pos) < 3:
        raise ValueError("tr: usage: tr path src dst")
    path, src, dst = _resolve(cwd, pos[0]), pos[1], pos[2]
    return search.tr(ws, path, src, dst)


def _mkdir(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("mkdir", argv, {"-p"})
    paths = [a for a in argv if not a.startswith("-")]
    if not paths:
        raise ValueError("mkdir: missing operand")
    write.mkdir(ws, _resolve(cwd, paths[0]))
    return ""


def _touch(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("touch", argv, set())
    paths = [a for a in argv if not a.startswith("-")]
    if not paths:
        raise ValueError("touch: missing operand")
    write.touch(ws, _resolve(cwd, paths[0]))
    return ""


def _cp(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("cp", argv, {"-r", "-R"})
    paths = [a for a in argv if not a.startswith("-")]
    if len(paths) < 2:
        raise ValueError("cp: requires src and dst")
    write.cp(ws, _resolve(cwd, paths[0]), _resolve(cwd, paths[1]))
    return ""


def _mv(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("mv", argv, set())
    paths = [a for a in argv if not a.startswith("-")]
    if len(paths) < 2:
        raise ValueError("mv: requires src and dst")
    write.mv(ws, _resolve(cwd, paths[0]), _resolve(cwd, paths[1]))
    return ""


def _rm(ws: Workspace, argv: list[str], cwd: str) -> str:
    _check_flags("rm", argv, {"-r", "-R", "-f", "-v"})
    recursive = any(
        a.startswith("-") and not a.startswith("--") and ("r" in a or "R" in a)
        for a in argv)
    force = any(
        a.startswith("-") and not a.startswith("--") and "f" in a
        for a in argv)
    verbose = any(
        a.startswith("-") and not a.startswith("--") and "v" in a
        for a in argv)
    paths = [a for a in argv if not a.startswith("-")]
    if not paths:
        raise ValueError("rm: missing operand")
    resolved = _resolve(cwd, paths[0])
    write.rm(ws, resolved, recursive=recursive, force=force)
    if verbose:
        return f"removed '{resolved}'"
    return ""


def _sed(ws: Workspace, argv: list[str], cwd: str) -> str:
    # NOTE: downloads full file; S3 Select could help for line-pattern matching
    _check_flags("sed", argv, {"-i", "-e"})
    pos = [a for a in argv if not a.startswith("-")]
    if len(pos) < 2:
        raise ValueError("sed: usage: sed s/pattern/replacement/ path")
    expr, path = pos[0], _resolve(cwd, pos[1])
    parts = expr.split("/")
    if len(parts) < 3 or parts[0] != "s":
        raise ValueError(f"sed: unsupported expression: {expr!r}")
    write.sed(ws, path, parts[1], parts[2])
    return ""


def _echo(ws: Workspace, argv: list[str], cwd: str) -> str:
    append = ">>" in argv
    if ">" in argv or ">>" in argv:
        redirect = ">>" if append else ">"
        idx = argv.index(redirect)
        content = " ".join(argv[:idx])
        path = _resolve(cwd, argv[idx + 1]) if idx + 1 < len(argv) else None
        if path:
            write.echo(ws, path, content + "\n", append=append)
            return ""
        return content
    return " ".join(argv)


def _tee(ws: Workspace, argv: list[str], cwd: str) -> str:
    pos = [a for a in argv if not a.startswith("-")]
    if not pos:
        raise ValueError("tee: missing operand")
    content = " ".join(argv[:-1])
    data = write.tee(ws, _resolve(cwd, pos[-1]), content.encode())
    return data.decode(errors="replace")


def _curl(ws: Workspace, argv: list[str], cwd: str) -> str:
    headers: dict[str, str] = {}
    urls = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-H" and i + 1 < len(argv):
            k, _, v = argv[i + 1].partition(":")
            headers[k.strip()] = v.strip()
            i += 2
        elif not a.startswith("-"):
            urls.append(a)
            i += 1
        else:
            i += 1
    if not urls:
        raise ValueError("curl: missing URL")
    return net.curl(urls[0], headers=headers).decode(errors="replace")


def _wget(ws: Workspace, argv: list[str], cwd: str) -> str:
    urls = [a for a in argv if not a.startswith("-")]
    if not urls:
        raise ValueError("wget: missing URL")
    url = urls[0]
    dest = _resolve(cwd, urls[1] if len(urls) > 1 else url.rsplit("/", 1)[-1])
    n = net.wget(url, dest, ws=ws)
    return f"saved {n} bytes to {dest}"


COMMANDS: dict[str, Callable[[Workspace, list[str], str], str]] = {
