import hashlib
import shlex
from typing import TYPE_CHECKING

from pydantic import BaseModel, ConfigDict

from mirage.commands import COMMANDS
from mirage.commands.custom.arg_resolver import classify_args
from mirage.commands.custom.executor import run_backend_method, run_external
from mirage.server.constants import _parse_size
from mirage.types import FilePayload, RemoteCommandOptions
from mirage.workspace import Workspace

if TYPE_CHECKING:
    from mirage.commands.remote.client import CommandClient


class ExternalCommand(BaseModel):
    model_config = ConfigDict(frozen=True)

    name: str
    exec: str
    description: str = ""
    options: RemoteCommandOptions = RemoteCommandOptions()


def _is_local_path(exec_str: str) -> bool:
    first = shlex.split(exec_str)[0] if exec_str.strip() else ""
    return first.startswith("/") or first.startswith("./")


def _md5(data: bytes) -> str:
    return hashlib.md5(data).hexdigest()


class CommandRegistry:

    def __init__(self, client: "CommandClient | None" = None) -> None:
        self._external: dict[str, ExternalCommand] = {}
        self._client = client

    def register(self, cmd: ExternalCommand) -> None:
        self._external[cmd.name] = cmd

    def list_commands(self) -> list[str]:
        return sorted(list(COMMANDS.keys()) + list(self._external.keys()))

    def run(self,
            ws: Workspace,
            command: str,
            cwd: str = "/",
            stdin: bytes | None = None) -> str:
        parts = shlex.split(command)
        if not parts:
            return ""
        cmd_name, argv = parts[0], parts[1:]

        if cmd_name in self._external:
            ext = self._external[cmd_name]
            if _is_local_path(ext.exec):
                return run_external(ws, ext, argv, cwd)
            if self._client is not None:
                return self._dispatch_to_client(ws, ext, cmd_name, argv, cwd,
                                                stdin)
            return run_external(ws, ext, argv, cwd)

        if cmd_name in COMMANDS:
            return COMMANDS[cmd_name](ws, argv, cwd)

        return run_backend_method(ws, cmd_name, argv, cwd)

    def _dispatch_to_client(self, ws: Workspace, ext: ExternalCommand,
                            cmd_name: str, argv: list[str], cwd: str,
                            stdin: bytes | None) -> str:
        classified = classify_args(ws, argv, cwd)
        max_size = _parse_size(ext.options.max_file_size)

        for vp in classified.potential_outputs:
            ws._assert_writable(vp)

        files: dict[str, FilePayload] | None = None
        if classified.input_files or classified.input_dirs:
            files = {}
            for vp, data in classified.input_files.items():
                if len(data) > max_size:
                    raise ValueError(
                        f"{vp} ({len(data)} bytes) exceeds max "
                        f"file size ({ext.options.max_file_size})")
                files[vp] = FilePayload(checksum=_md5(data), data=data)
            for dir_files in classified.input_dirs.values():
                for file_vp, data in dir_files.items():
                    if len(data) > max_size:
                        raise ValueError(
                            f"{file_vp} ({len(data)} bytes) exceeds max "
                            f"file size ({ext.options.max_file_size})")
                    files[file_vp] = FilePayload(checksum=_md5(data),
                                                 data=data)

        all_virtual_paths = (list(classified.input_files.keys()) +
                             list(classified.potential_outputs))
        for dir_files in classified.input_dirs.values():
            all_virtual_paths.extend(dir_files.keys())

        full_command = " ".join([cmd_name] + argv)

        # Lock paths during remote execution to prevent local writes
        # from racing with the remote command.
        ws._locked_paths.update(all_virtual_paths)
        try:
            result = self._client.run(full_command,
                                      cwd=cwd,
                                      stdin=stdin,
                                      files=files)
        finally:
            ws.unlock_paths(all_virtual_paths)

        for path, data in result.output_files.items():
            ws.write(path, data)

        return result.stdout

import base64
from abc import ABC, abstractmethod

import grpc
import httpx

from mirage.commands.remote.auth import ClientAuth, NoAuth
from mirage.commands.remote.grpc.proto import command_pb2, command_pb2_grpc
from mirage.types import CommandResult, FilePayload


class CommandClientError(Exception):
    pass


class CommandClient(ABC):

    @abstractmethod
    def list_commands(self) -> list[str]:
        ...

    @abstractmethod
    def run(
        self,
        command: str,
        cwd: str = "/",
        stdin: bytes | None = None,
        files: dict[str, FilePayload] | None = None,
    ) -> CommandResult:
        ...

    @abstractmethod
    def register_command(self,
                         name: str,
                         exec_template: str,
                         description: str = "") -> None:
        ...


class HTTPCommandClient(CommandClient):

    def __init__(self,
                 base_url: str,
                 auth: ClientAuth = NoAuth(),
                 timeout: int = 30) -> None:
        self._base_url = base_url.rstrip("/")
        self._client = httpx.Client(headers=auth.headers(), timeout=timeout)

    def list_commands(self) -> list[str]:
        resp = self._client.get(f"{self._base_url}/commands")
        if resp.status_code != 200:
            raise CommandClientError(
                f"list_commands failed: {resp.status_code}")
        return resp.json()

    def run(
        self,
        command: str,
        cwd: str = "/",
        stdin: bytes | None = None,
        files: dict[str, FilePayload] | None = None,
    ) -> CommandResult:
        body: dict = {"command": command, "cwd": cwd}
        if stdin is not None:
            body["stdin"] = base64.b64encode(stdin).decode()
        if files:
            body["input_files"] = {}
            for path, payload in files.items():
                entry: dict = {"checksum": payload.checksum}
                entry["data"] = (base64.b64encode(payload.data).decode()
                                 if payload.data is not None else None)
                body["input_files"][path] = entry

        resp = self._client.post(f"{self._base_url}/run", json=body)
        if resp.status_code == 412:
            data = resp.json()
            missing = data.get("missing", [])
            raise CommandClientError(f"cache miss for files: {missing}")
        if resp.status_code != 200:
            raise CommandClientError(f"run failed: {resp.status_code}")
        data = resp.json()
        if not data.get("ok"):
            raise CommandClientError(data.get("error", "unknown error"))

        output_files: dict[str, bytes] = {}
        for path, file_data in (data.get("output_files") or {}).items():
            output_files[path] = base64.b64decode(file_data["data"])

        return CommandResult(
            stdout=data.get("output", ""),
            output_files=output_files,
        )

    def register_command(self,
                         name: str,
                         exec_template: str,
                         description: str = "") -> None:
        resp = self._client.post(f"{self._base_url}/register",
                                 json={
                                     "name": name,
                                     "exec": exec_template,
                                     "description": description
                                 })
        if resp.status_code != 200:
            raise CommandClientError(
                f"register_command failed: {resp.status_code}")
        data = resp.json()
        if not data.get("ok"):
            raise CommandClientError(data.get("error", "unknown error"))


class GRPCCommandClient(CommandClient):

    def __init__(self,
                 host: str,
                 port: int = 50051,
                 auth: ClientAuth = NoAuth()) -> None:
        self._auth = auth
        self._channel = grpc.insecure_channel(f"{host}:{port}")
        self._stub = command_pb2_grpc.CommandServiceStub(self._channel)

    def _metadata(self) -> list[tuple[str, str]]:
        return list(self._auth.headers().items())

    def list_commands(self) -> list[str]:
        try:
            resp = self._stub.ListCommands(command_pb2.ListCommandsRequest(),
                                           metadata=self._metadata())
            return list(resp.commands)
        except grpc.RpcError as e:
            raise CommandClientError(str(e)) from e

    def run(
        self,
        command: str,
        cwd: str = "/",
        stdin: bytes | None = None,
        files: dict[str, FilePayload] | None = None,
    ) -> CommandResult:
        input_files = {}
        if files:
            for path, payload in files.items():
                input_files[path] = command_pb2.FilePayload(
                    checksum=payload.checksum,
                    data=payload.data or b"",
                )
        try:
            resp = self._stub.RunCommand(
                command_pb2.RunCommandRequest(
                    command=command,
                    cwd=cwd,
                    stdin=stdin or b"",
                    input_files=input_files,
                ),
                metadata=self._metadata(),
            )
            if not resp.ok:
                raise CommandClientError(resp.error)
            output_files: dict[str, bytes] = {}
            for path, out_file in resp.output_files.items():
                output_files[path] = out_file.data
            return CommandResult(stdout=resp.output, output_files=output_files)
        except grpc.RpcError as e:
            raise CommandClientError(str(e)) from e

    def register_command(self,
                         name: str,
                         exec_template: str,
                         description: str = "") -> None:
        try:
            resp = self._stub.RegisterCommand(
                command_pb2.RegisterCommandRequest(name=name,
                                                   exec=exec_template,
                                                   description=description),
                metadata=self._metadata())
            if not resp.ok:
                raise CommandClientError(resp.error)
        except grpc.RpcError as e:
            raise CommandClientError(str(e)) from e

    def close(self) -> None:
        self._channel.close()

    def __enter__(self) -> "GRPCCommandClient":
        return self

    def __exit__(self, *_: object) -> None:
        self.close()

import os
import resource
import time
from typing import TYPE_CHECKING, Any

from mirage.backend.local.memory import MemoryBackend
from mirage.commands import COMMAND_COST, COMMANDS
from mirage.types import CostLevel

if TYPE_CHECKING:
    from mirage.workspace import Workspace

_server_start_time: float = 0.0


def _count_dirty(ws: "Workspace") -> int:
    memory_mounts = {
        m.prefix
        for m in ws._registry.mounts() if isinstance(m.backend, MemoryBackend)
    }
    return len([
        i for i in ws._tracker.dirty() if i.backend_mount not in memory_mounts
    ])


def set_server_start_time(t: float) -> None:
    global _server_start_time
    _server_start_time = t


def global_status(sessions: dict[str, Any]) -> dict:
    rss = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    if os.uname().sysname == "Darwin":
        rss_bytes = rss
    else:
        rss_bytes = rss * 1024
    total_cache = 0
    for s in sessions.values():
        if s.ws is not None:
            total_cache += s.ws._cache.size
    uptime_s = int(time.monotonic() - _server_start_time)
    return {
        "rss_bytes": rss_bytes,
        "total_sessions": len(sessions),
        "total_cache_bytes": total_cache,
        "uptime_seconds": uptime_s,
    }


def list_sessions(sessions: dict[str, Any]) -> list[dict]:
    results = []
    for s in sessions.values():
        entry: dict[str, Any] = {
            "id": s.id,
            "fuse_mounted": s.fuse_mounted,
            "mode": s.mode,
            "mounts": s.mounts,
        }
        if s.ws is not None:
            entry["cache_used"] = s.ws._cache.size
            entry["cache_limit"] = s.ws._cache.limit
            entry["dirty_count"] = len(s.ws._tracker.dirty())
            entry["total_commands"] = s.command_stats.total_commands
        results.append(entry)
    return results


def workspace_status(session: Any) -> dict:
    ws: Workspace = session.ws
    backends_health = []
    for mount in ws._registry.mounts():
        backends_health.append({
            "mount": mount.prefix,
            "backend": type(mount.backend).__name__,
        })
    return {
        "cache_used": ws._cache.size,
        "cache_limit": ws._cache.limit,
        "dirty_inodes": _count_dirty(ws),
        "backends": backends_health,
        "last_command": session.command_stats.last_command,
        "total_commands": session.command_stats.total_commands,
        "total_errors": session.command_stats.total_errors,
    }


def workspace_commands(session: Any) -> list[dict]:
    result = []
    for name in sorted(COMMANDS.keys()):
        cost = COMMAND_COST.get(name, CostLevel.CHEAP)
        result.append({
            "name": name,
            "source": "builtin",
            "cost_level": cost.value,
        })
    for name, ext in session.registry._external.items():
        result.append({
            "name": name,
            "source": "external",
            "cost_level": "unknown",
            "description": ext.description,
            "exec": ext.exec,
        })
    return result


def workspace_memory(session: Any) -> dict:
    ws: Workspace = session.ws
    cache_entries = {}
    for path, entry in ws._cache._store.items():
        cache_entries[path] = len(entry.data)
    dirty_paths = [i.virtual_path for i in ws._tracker.dirty()]
    backend_memory: dict[str, dict] = {}
    for mount in ws._registry.mounts():
        if isinstance(mount.backend, MemoryBackend):
            total = sum(len(v) for v in mount.backend._files.values())
            backend_memory[mount.prefix] = {
                "type": "MemoryBackend",
                "file_count": len(mount.backend._files),
                "total_bytes": total,
            }
    return {
        "cache": {
            "used": ws._cache.size,
            "limit": ws._cache.limit,
            "entry_count": len(ws._cache._store),
            "entries": cache_entries,
        },
        "dirty_tracker": {
            "total_inodes": len(ws._tracker._inodes),
            "dirty_paths": dirty_paths,
        },
        "backend_memory": backend_memory,
    }


def workspace_transfers(session: Any) -> dict:
    ws: Workspace = session.ws
    return workspace_transfers_from_ws(ws)


def workspace_status_from_ws(ws: "Workspace") -> dict:
    backends_health = []
    for mount in ws._registry.mounts():
        backends_health.append({
            "mount": mount.prefix,
            "backend": type(mount.backend).__name__,
        })
    return {
        "cache_used": ws._cache.size,
        "cache_limit": ws._cache.limit,
        "dirty_inodes": _count_dirty(ws),
        "backends": backends_health,
        "last_command": None,
        "total_commands": 0,
        "total_errors": 0,
    }


def workspace_transfers_from_ws(ws: "Workspace") -> dict:
    per_backend: dict[str, dict] = {}
    for prefix, stats in ws._transfer_stats.items():
        total_reads = stats.read_ops
        avg_read_ms = (stats.total_read_ms /
                       total_reads if total_reads > 0 else 0)
        total_cache_ops = stats.cache_hits + stats.cache_misses
        hit_rate = (stats.cache_hits /
                    total_cache_ops if total_cache_ops > 0 else 0.0)
        per_backend[prefix] = {
            "bytes_read": stats.bytes_read,
            "bytes_written": stats.bytes_written,
            "read_ops": stats.read_ops,
            "write_ops": stats.write_ops,
            "avg_read_latency_ms": round(avg_read_ms, 1),
            "cache_hit_rate": round(hit_rate, 3),
        }
    return per_backend

