from mirage.backend.local.memory import MemoryBackend
from mirage.commands import COMMAND_COST, COMMANDS
from mirage.types import CostLevel
from mirage.workspace import Workspace


def test_commands_has_ls():
    assert "ls" in COMMANDS


def test_ls_handler(write_ws):
    write_ws.write("/tmp/a.txt", b"hello")
    result = COMMANDS["ls"](write_ws, [], "/tmp/")
    assert "a.txt" in result


def test_cat_handler(write_ws):
    write_ws.write("/tmp/f.txt", b"world")
    result = COMMANDS["cat"](write_ws, ["/tmp/f.txt"], "/")
    assert result == "world"


def test_pwd_handler():
    ws = Workspace({"/tmp/": MemoryBackend()})
    result = COMMANDS["pwd"](ws, [], "/tmp/")
    assert result == "/tmp/"


def test_head_handler(write_ws):
    lines = "\n".join(f"line{i}" for i in range(20))
    write_ws.write("/tmp/f.txt", lines.encode())
    result = COMMANDS["head"](write_ws, ["-n", "3", "/tmp/f.txt"], "/")
    assert result == "line0\nline1\nline2"


def test_tail_handler(write_ws):
    lines = "\n".join(f"line{i}" for i in range(20))
    write_ws.write("/tmp/f.txt", lines.encode())
    result = COMMANDS["tail"](write_ws, ["-n", "3", "/tmp/f.txt"], "/")
    assert result == "line17\nline18\nline19"


def test_command_cost_cheap_commands():
    for cmd in ("ls", "stat", "find", "mkdir", "rm"):
        assert COMMAND_COST[cmd] == CostLevel.CHEAP


def test_command_cost_partial_commands():
    for cmd in ("head", "tail", "grep"):
        assert COMMAND_COST[cmd] == CostLevel.PARTIAL


def test_command_cost_expensive_commands():
    for cmd in ("cat", "wc", "md5", "sort", "uniq"):
        assert COMMAND_COST[cmd] == CostLevel.EXPENSIVE


def test_command_cost_network_commands():
    for cmd in ("curl", "wget"):
        assert COMMAND_COST[cmd] == CostLevel.NETWORK


def test_all_commands_have_cost():
    for cmd in COMMANDS:
        assert cmd in COMMAND_COST, f"missing cost for {cmd!r}"

